namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public required string Summary { get; set; }
    public int OriginalWordCount { get; set; }
    public int SummaryWordCount { get; set; }
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

public partial class DocumentSummarizationService
{
    // Common English stop words excluded from scoring
    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
    {
        "a","an","the","and","or","but","is","are","was","were","be","been",
        "being","have","has","had","do","does","did","will","would","shall",
        "should","may","might","must","can","could","in","on","at","to","for",
        "with","from","by","of","about","into","through","during","before",
        "after","above","below","between","out","up","down","this","that",
        "these","those","it","its","he","she","they","we","you","i","me",
        "him","her","us","them","my","your","his","our","their","not","no",
        "nor","so","if","then","than","too","very","just","also","as","such"
    };

    [GeneratedRegex(@"(?<=[.!?])\s+")]
    private static partial Regex SentenceSplitter();

    [GeneratedRegex(@"\b\w+\b")]
    private static partial Regex WordMatcher();

    /// <summary>
    /// Produces an extractive summary by scoring sentences based on word frequency.
    /// </summary>
    public string Summarize(string text, int maxSentences)
    {
        if (string.IsNullOrWhiteSpace(text))
            return string.Empty;

        maxSentences = Math.Max(1, maxSentences);

        var sentences = SentenceSplitter()
            .Split(text)
            .Select(s => s.Trim())
            .Where(s => s.Length > 0)
            .ToList();

        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        // Build word-frequency map (excluding stop words)
        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var sentence in sentences)
        {
            foreach (Match match in WordMatcher().Matches(sentence))
            {
                var word = match.Value;
                if (!StopWords.Contains(word) && word.Length > 1)
                {
                    wordFrequency.TryGetValue(word, out int count);
                    wordFrequency[word] = count + 1;
                }
            }
        }

        // Score each sentence by summing the frequencies of its non-stop words
        var scored = sentences
            .Select((sentence, index) =>
            {
                double score = WordMatcher().Matches(sentence)
                    .Where(m => wordFrequency.ContainsKey(m.Value))
                    .Sum(m => wordFrequency[m.Value]);

                // Normalize by word count to avoid bias toward long sentences
                int wordCount = WordMatcher().Matches(sentence).Count;
                if (wordCount > 0)
                    score /= wordCount;

                return new { Sentence = sentence, Index = index, Score = score };
            })
            .ToList();

        // Pick the top-scored sentences, preserving their original order
        var topSentences = scored
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index)
            .Select(s => s.Sentence);

        return string.Join(" ", topSentences);
    }

    public int CountWords(string text) =>
        string.IsNullOrWhiteSpace(text) ? 0 : WordMatcher().Matches(text).Count;
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly DocumentSummarizationService _service;

    public SummaryController(DocumentSummarizationService service)
    {
        _service = service;
    }

    /// <summary>
    /// Accepts document text and returns a concise extractive summary.
    /// </summary>
    [HttpPost]
    public IActionResult Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest(new { error = "DocumentText must not be empty." });

        var summary = _service.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalWordCount = _service.CountWords(request.DocumentText),
            SummaryWordCount = _service.CountWords(summary)
        });
    }
}

