+    [GeneratedRegex(@"(?<=[.!?])\s+")]
+    private static partial Regex SentenceSplitter();
+
+    [GeneratedRegex(@"\b\w+\b")]
+    private static partial Regex WordMatcher();
+
+    /// <summary>
+    /// Produces an extractive summary by scoring sentences based on word frequency.
+    /// </summary>
+    public string Summarize(string text, int maxSentences)
+    {
+        if (string.IsNullOrWhiteSpace(text))
+            return string.Empty;
+
+        maxSentences = Math.Max(1, maxSentences);
+
+        var sentences = SentenceSplitter()
+            .Split(text)
+            .Select(s => s.Trim())
+            .Where(s => s.Length > 0)
+            .ToList();
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        // Build word-frequency map (excluding stop words)
+        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (Match match in WordMatcher().Matches(sentence))
+            {
+                var word = match.Value;
+                if (!StopWords.Contains(word) && word.Length > 1)
+                {
+                    wordFrequency.TryGetValue(word, out int count);
+                    wordFrequency[word] = count + 1;
+                }
+            }
+        }
+
+        // Score each sentence by summing the frequencies of its non-stop words
+        var scored = sentences
+            .Select((sentence, index) =>
+            {
+                double score = WordMatcher().Matches(sentence)
+                    .Where(m => wordFrequency.ContainsKey(m.Value))
+                    .Sum(m => wordFrequency[m.Value]);
+
+                // Normalize by word count to avoid bias toward long sentences
+                int wordCount = WordMatcher().Matches(sentence).Count;
+                if (wordCount > 0)
+                    score /= wordCount;
+
+                return new { Sentence = sentence, Index = index, Score = score };
+            })
+            .ToList();
+
+        // Pick the top-scored sentences, preserving their original order
+        var topSentences = scored
+            .OrderByDescending(s => s.Score)
+            .Take(maxSentences)
+            .OrderBy(s => s.Index)
+            .Select(s => s.Sentence);
+
+        return string.Join(" ", topSentences);
+    }
+
+    public int CountWords(string text) =>
+        string.IsNullOrWhiteSpace(text) ? 0 : WordMatcher().Matches(text).Count;
+}
